BEGIN;
-- V15.6: permanent deletion, independent night generations and source-backed choices.
-- No user record is deleted when this migration is installed.
do $$ begin
 if to_regprocedure('journal_cr_private.api_v155(text,jsonb)') is null then
  alter function public.journal_cr_api(text,jsonb) set schema journal_cr_private;
  alter function journal_cr_private.journal_cr_api(text,jsonb) rename to api_v155;
 end if;
end $$;
create table if not exists journal_cr_private.night_resets (
 chantier_id uuid references public.chantiers(id) on delete cascade,
 night date not null, reset_at timestamptz not null, primary key(chantier_id,night)
);
-- Only a cutoff, never a restorable report or answers. It prevents old production reuse.
create table if not exists journal_cr_private.references_v156 (
 id text primary key, section_key text not null check(section_key in ('itc','catenaire')),
 type text not null check(type in ('SEL','Secteur','ZEP')), label text not null,
 reference text not null, sector text not null default '', sites jsonb not null, sources jsonb not null
);
