create or replace function journal_cr_private.field_choices(p_id uuid,p_key text) returns jsonb language sql stable set search_path='' as $$
 select coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('chantier',array_to_string(array(select jsonb_array_elements_text(c.sites)),', ')) order by c.type,c.label),'[]')
 from journal_cr_private.references_v156 c where c.section_key=p_key;
$$;
create or replace function journal_cr_private.erase_report_data() returns trigger language plpgsql security definer set search_path='' as $$
begin
 -- Cascaded chantier deletion needs no cutoff: the chantier itself disappears.
 if exists(select 1 from public.chantiers where id=old.chantier_id) then
  insert into journal_cr_private.night_resets values(old.chantier_id,old.night,clock_timestamp())
  on conflict(chantier_id,night) do update set reset_at=excluded.reset_at;
 end if;
 -- Old email envelopes contain copies outside the report FK graph. Remove the
 -- deleted report from these envelopes, retaining other reports' own snapshots.
 update journal_cr_private.deliveries set report_ids=array_remove(report_ids,old.id),
 snapshots=coalesce((select jsonb_agg(x) from jsonb_array_elements(snapshots) x where coalesce(x->>'id',x->>'report_id','')<>old.id::text),'[]'),
 body='',subject='CR off',recipients='[]',state=case when state='pending' then 'failed' else state end,error_code='report_permanently_deleted'
 where old.id=any(report_ids);
 delete from journal_cr_private.deliveries where cardinality(report_ids)=0;
 return old;
end $$;
drop trigger if exists cr_erase_data on journal_cr_private.reports;
create trigger cr_erase_data before delete on journal_cr_private.reports for each row execute function journal_cr_private.erase_report_data();
create or replace function journal_cr_private.sync_production(p_site uuid,p_night date) returns void language plpgsql security definer set search_path='' as $$
declare sheets jsonb;lines jsonb;complete boolean;
begin
 select coalesce(jsonb_agg(to_jsonb(p) order by p.created_at,p.id),'[]') into sheets from journal_cr_private.production_sheets p where chantier_id=p_site and night=p_night and p.created_at>coalesce((select reset_at from journal_cr_private.night_resets where chantier_id=p_site and night=p_night),'-infinity'::timestamptz);
 if jsonb_array_length(sheets)=0 then return;end if;
 select jsonb_agg(x),bool_and(x->>'progress' is not null) into lines,complete from jsonb_array_elements(sheets) s cross join lateral jsonb_array_elements(s->'items') x;
 update journal_cr_private.sections s set value=s.value||jsonb_build_object('production_sheets',sheets,'production_text',journal_cr_private.production_text(lines)),
 status=case when s.value->>'production_mode'='text' then case when length(trim(coalesce(s.value->>'body','')))>0 then 'complete' else 'a_renseigner' end when complete then 'complete' else 'en_cours' end,version=s.version+1
 from journal_cr_private.reports r where s.report_id=r.id and s.key='technique' and r.chantier_id=p_site and r.night=p_night and r.state='draft' and r.deleted_at is null
 and s.value->'production_sheets' is distinct from sheets;
 update journal_cr_private.field_requests request_row set base_version=section_row.version,
 draft=jsonb_set(request_row.draft,'{sheets}',sheets),version=request_row.version+1
 from journal_cr_private.sections section_row join journal_cr_private.reports report_row on report_row.id=section_row.report_id
 where request_row.report_id=report_row.id and request_row.section_key='technique' and section_row.key='technique'
 and report_row.chantier_id=p_site and report_row.night=p_night and report_row.deleted_at is null and report_row.state='draft'
 and request_row.state='open' and request_row.saved_at is null and request_row.base_version<>section_row.version;
end $$;
create or replace function public.journal_production_api(p_action text,p_payload jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
declare sid uuid:=(p_payload->>'chantier_id')::uuid;d date:=(p_payload->>'night')::date;rid uuid;result jsonb;
begin
 if auth.uid() is null or not public.journal_v142_is_active() or not journal_cr_private.member(auth.uid(),sid) then raise exception 'Production inaccessible';end if;
 if p_action='save' then
  if not (public.journal_v142_can_write(sid) or journal_cr_private.can_fill_production(sid,d)) then raise exception 'Accès en écriture requis';end if;
  perform pg_advisory_xact_lock(hashtextextended(sid::text||d::text,0));
  if exists(select 1 from journal_cr_private.field_requests q join journal_cr_private.reports r on r.id=q.report_id where r.chantier_id=sid and r.night=d and r.deleted_at is null and q.section_key='technique' and q.state='submitted') and not journal_cr_private.manager(sid) then raise exception 'Informations transmises : demander une correction à l’administrateur';end if;
  if not exists(select 1 from journal_cr_private.night_resets z join journal_cr_private.production_sheets p on p.chantier_id=z.chantier_id and p.night=z.night
    where z.chantier_id=sid and z.night=d and p.id=(p_payload->>'id')::uuid and p.created_at<=z.reset_at) then
   rid:=journal_cr_private.ensure_report(sid,d,auth.uid());
  end if;
 end if;
 result:=journal_cr_private.production_api_v154(p_action,p_payload);
 return result;
end $$;

create or replace function public.journal_cr_api(p_action text,p_payload jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid();ids uuid[];rid uuid;sid uuid;d date;r journal_cr_private.reports;result jsonb;
begin
 if uid is null or not public.journal_v142_is_active() then raise exception 'Connexion active requise';end if;
 if octet_length(p_payload::text)>300000 then raise exception 'Demande trop volumineuse';end if;
 if p_action='restore_reports' then raise exception 'La restauration est supprimée. Préparez un nouveau CR vierge.';
 elsif p_action='list' then
  if coalesce((p_payload->>'deleted')::boolean,false) then return '[]';end if;
  -- Previously soft-deleted documents can be explicitly erased, never restored.
  return journal_cr_private.api_v155('list',p_payload||'{"deleted":false}')||
   case when coalesce((p_payload->>'offset')::int,0)=0 then journal_cr_private.api_v155('list','{"deleted":true}') else '[]'::jsonb end;
 elsif p_action='delete_reports' then
  select array_agg(distinct v::uuid) into ids from jsonb_array_elements_text(p_payload->'ids') v;
  if coalesce(cardinality(ids),0) not between 1 and 200 then raise exception 'Sélectionner les CR concernés';end if;
  if exists(select 1 from journal_cr_private.reports where id=any(ids) and not (journal_cr_private.manager(chantier_id) and journal_cr_private.member(uid,chantier_id))) then raise exception 'Suppression réservée aux administrateurs des chantiers concernés';end if;
  -- Lock in the same order as submissions and creation; retries of an erased UUID are harmless.
  for r in select * from journal_cr_private.reports where id=any(ids) order by chantier_id,night loop
   perform pg_advisory_xact_lock(hashtextextended(r.chantier_id::text||r.night::text,0));
  end loop;
  delete from journal_cr_private.reports where id=any(ids) and journal_cr_private.manager(chantier_id) and journal_cr_private.member(uid,chantier_id);
  return '{"deleted":true}';
 elsif p_action='create' then
  sid:=(p_payload->>'chantier_id')::uuid;d:=(p_payload->>'night')::date;
  if not journal_cr_private.manager(sid) or not journal_cr_private.member(uid,sid) then raise exception 'Préparation réservée à l’administrateur du chantier';end if;
  if d is null or d not between current_date-366 and current_date+31 then raise exception 'Date de nuit invalide';end if;
  perform pg_advisory_xact_lock(hashtextextended(sid::text||d::text,0));
  -- An old soft removal cannot occupy this night or restore its former content.
  delete from journal_cr_private.reports where chantier_id=sid and night=d and deleted_at is not null;
  if exists(select 1 from journal_cr_private.night_resets where chantier_id=sid and night=d) then
   p_payload:=p_payload||'{"reuse":false}';
  end if;
 end if;
 return journal_cr_private.api_v155(p_action,p_payload);
end $$;
revoke all on all tables in schema journal_cr_private from public,anon,authenticated,service_role;
revoke all on all functions in schema journal_cr_private from public,anon,authenticated,service_role;
revoke all on function public.journal_cr_api(text,jsonb),public.journal_production_api(text,jsonb) from public,anon;
grant execute on function public.journal_cr_api(text,jsonb),public.journal_production_api(text,jsonb) to authenticated;
create or replace function public.journal_delete_site_v156(p_chantier_id uuid) returns void language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null or not public.journal_v142_is_active() or not exists(select 1 from public.journal_administrators where user_id=auth.uid() and role='proprietaire') then raise exception 'Suppression du chantier réservée au propriétaire principal';end if;
 -- Reuse historical cleanup when installed, including legacy foreign keys.
 if to_regprocedure('public.delete_journal_chantier(uuid)') is not null then
  perform public.delete_journal_chantier(p_chantier_id);
 end if;
 -- These legacy tables do not consistently declare ON DELETE CASCADE.
 delete from public.chantier_read_states where chantier_id=p_chantier_id;
 delete from public.chantier_message_reactions where chantier_id=p_chantier_id;
 delete from public.chantier_attachments where chantier_id=p_chantier_id;
 delete from public.chantier_daily_logs where chantier_id=p_chantier_id;
 delete from public.chantier_risks where chantier_id=p_chantier_id;
 delete from public.chantier_invitations where chantier_id=p_chantier_id;
 delete from public.chantiers where id=p_chantier_id;
end $$;
revoke all on function public.journal_delete_site_v156(uuid) from public,anon,service_role;
grant execute on function public.journal_delete_site_v156(uuid) to authenticated;

create table if not exists journal_cr_private.writing_usage(user_id uuid,hour timestamptz,requests int not null,primary key(user_id,hour));
create or replace function public.journal_writing_access(p_site uuid,p_count boolean default true) returns boolean language plpgsql security definer set search_path='' as $$
declare n int;
begin
 if auth.uid() is null or not public.journal_v142_is_active() or not journal_cr_private.member(auth.uid(),p_site) then return false;end if;
 if not p_count then return true;end if;
 insert into journal_cr_private.writing_usage values(auth.uid(),date_trunc('hour',now()),1)
 on conflict(user_id,hour) do update set requests=journal_cr_private.writing_usage.requests+1 returning requests into n;
 delete from journal_cr_private.writing_usage where hour<now()-interval '2 days';return n<=30;
end $$;
revoke all on journal_cr_private.writing_usage from public,anon,authenticated,service_role;
revoke all on function public.journal_writing_access(uuid,boolean) from public,anon,service_role;
grant execute on function public.journal_writing_access(uuid,boolean) to authenticated;
NOTIFY pgrst,'reload schema';
COMMIT;
